def dL(w):
    return 2 * (w - 3)

for lr in [0.01, 0.2, 1.1]:
    w = -2.0
    for langkah in range(20):
        w = w - lr * dL(w)
    print(f'lr={lr:<4}: w setelah 20 langkah = {w:.3f}')

def biaya(x):
    return 0.5 * x ** 2 - 40 * x + 1000      # biaya produksi (ribu) untuk x unit

def turunan_rumus(x):
    return x - 40

h = 1e-4
for x in [10, 40, 70]:
    numerik = (biaya(x + h) - biaya(x - h)) / (2 * h)
    print(f'x={x}: numerik={numerik:.4f}, rumus={turunan_rumus(x)}')
print('turunan nol di x=40, jadi biaya per unit paling hemat di sana')

import numpy as np
from scipy import stats

def n_per_grup(p0, naik, alpha=0.05, power=0.8):
    p1 = p0 + naik
    za, zb = stats.norm.ppf(1 - alpha / 2), stats.norm.ppf(power)
    pb = (p0 + p1) / 2
    return int(np.ceil((za * np.sqrt(2 * pb * (1 - pb)) + zb * np.sqrt(p0 * (1 - p0) + p1 * (1 - p1))) ** 2 / naik ** 2))

for naik in [0.010, 0.005, 0.0025]:
    print(f'CTR 2% -> {0.02 + naik:.2%}: {n_per_grup(0.02, naik):,} pengguna per grup')

