import numpy as np

def gini(y):
    if len(y) == 0:
        return 0
    p = np.bincount(y, minlength=2) / len(y)
    return 1 - (p ** 2).sum()

umur = np.array([19, 22, 24, 27, 31, 35, 38, 42, 47, 53])
beli_asuransi = np.array([0, 0, 0, 0, 1, 0, 1, 1, 1, 1])
for t in [24, 27, 31, 35, 38]:
    kiri, kanan = beli_asuransi[umur <= t], beli_asuransi[umur > t]
    g = (len(kiri) * gini(kiri) + len(kanan) * gini(kanan)) / len(umur)
    print(f'umur <= {t}: Gini tertimbang = {g:.3f}')

