import numpy as np

def softmax(z):
    e = np.exp(z - z.max())
    return e / e.sum()

kata = ['enak', 'mahal', 'pedas']
skor = np.array([2.0, 1.0, 0.5])
for suhu in [0.5, 1.0, 2.0]:
    p = softmax(skor / suhu)
    print(f'temperature {suhu}:', dict(zip(kata, p.round(2).tolist())))

