import numpy as np

emb = {'bayar': np.array([0.9, 0.1, 0.0]), 'qris': np.array([0.8, 0.0, 0.1]),
       'paket': np.array([0.0, 0.9, 0.1]), 'kirim': np.array([0.1, 0.8, 0.0]),
       'sandi': np.array([0.0, 0.1, 0.9]), 'lupa': np.array([0.1, 0.0, 0.7])}

def kalimat(teks):
    return np.mean([emb[k] for k in teks.split() if k in emb], axis=0)

def cos(a, b):
    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))

faq = ['bayar qris', 'kirim paket', 'lupa sandi']
tanya = kalimat('paket belum kirim')
for f in faq:
    print(f'{f:12}: {cos(tanya, kalimat(f)):.2f}')

