import numpy as np

def skor_dari_pd(pd_):
    odds = (1 - pd_) / pd_
    return 600 + 20 / np.log(2) * np.log(odds / 50)

def pd_dari_skor(skor):
    odds = 50 * 2 ** ((skor - 600) / 20)
    return 1 / (1 + odds)

for p in [0.20, 0.05, 0.0196, 0.01]:
    print(f'PD {p:.4f} -> skor {skor_dari_pd(p):.0f}')
print(f'skor 640 -> PD {pd_dari_skor(640):.4f}')
